#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_faBright;
uniform float amzp_faContrast;
uniform float amzp_faHigh;
uniform float amzp_faShadow;
uniform float amzp_faWhite;
uniform float amzp_faBlack;
uniform float amzp_faTemp;
uniform float amzp_faTint;
uniform float amzp_faSat;
uniform float amzp_faVib;
uniform float amzp_faHue;
        float lumY(float3 c) { return dot(c, float3(0.2126, 0.7152, 0.0722)); }
        float sCurve(float x, float s) {
            x = clamp(x, 0.0, 1.0);
            return x < 0.5 ? 0.5 * pow(2.0 * x, s) : 1.0 - 0.5 * pow(2.0 * (1.0 - x), s);
        }
        float3 hueRot(float3 c, float a) {
            float cs = cos(a), sn = sin(a);
            float3 k = float3(0.57735);
            return c * cs + cross(k, c) * sn + k * dot(k, c) * (1.0 - cs);
        }
        void amzRender() {
            float4 src = amzTexture(0, amzScreenNorm());
            float a = src.a;
            if (a <= 0.0001) {
                amzOutput = float4(0.0);
                return;
            }
            float3 c = clamp(src.rgb / a, 0.0, 1.0);
            float3 lin = pow(c, float3(2.2));
            lin *= exp2(amzp_faBright / 100.0 * 2.0);
            float tp = amzp_faTemp / 100.0, tn = amzp_faTint / 100.0;
            float3 wb = float3(1.0 + 0.32 * tp, 1.0 + 0.04 * tp, 1.0 - 0.42 * tp);
            wb *= float3(1.0 + 0.16 * tn, 1.0 - 0.26 * tn, 1.0 + 0.16 * tn);
            wb = max(wb, float3(0.0));
            wb /= max(lumY(wb), 0.0001);
            lin *= wb;
            c = pow(max(lin, float3(0.0)), float3(1.0 / 2.2));
            float s = exp2(amzp_faContrast / 100.0 * 1.2);
            if (amzp_faContrast != 0.0) c = float3(sCurve(c.r, s), sCurve(c.g, s), sCurve(c.b, s));
            float L = clamp(lumY(c), 0.0, 1.0);
            float d = 0.0;
            d += amzp_faHigh / 100.0 * 0.6 * (L * L * (1.0 - L) * 2.4);
            d += amzp_faShadow / 100.0 * 0.6 * (L * (1.0 - L) * (1.0 - L) * 2.4);
            d += amzp_faWhite / 100.0 * 0.3 * L * L * L;
            d += amzp_faBlack / 100.0 * 0.3 * (1.0 - L) * (1.0 - L) * (1.0 - L);
            c += d;
            float L2 = lumY(c);
            float mx = max(c.r, max(c.g, c.b)), mn = min(c.r, min(c.g, c.b));
            float sat0 = mx > 0.0001 ? clamp((mx - mn) / mx, 0.0, 1.0) : 0.0;
            float vb = amzp_faVib / 100.0;
            float k = 1.0 + amzp_faSat / 100.0 + (vb > 0.0 ? vb * (1.0 - sat0) : vb);
            c = mix(float3(L2), c, max(k, 0.0));
            if (amzp_faHue != 0.0) c = hueRot(c, amzp_faHue / 100.0 * 3.14159265);
            c = clamp(c, 0.0, 1.0);
            amzOutput = float4(c * a, a);
        }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
